  const values=new Float32Array(first.values.length),confidence=new Float32Array(values.length);let streak=0,on=false,until=0;const required=Math.max(1,Math.ceil(debounce*first.sampleRateHz)),minimum=Math.ceil(hold*first.sampleRateHz);
