export function signalRanges(signal:Signal):Range[]{const out:Range[]=[];let start=-1,confidence=1;for(let i=0;i<=signal.values.length;i++){if(i<signal.values.length&&signal.values[i]>.5){if(start<0)start=i;confidence=Math.min(confidence,signal.confidence[i]);}else if(start>=0){out.push({start:start/signal.sampleRateHz,end:i/signal.sampleRateHz,confidence});start=-1;confidence=1;}}return out;}
export function priority(signals:Record<string,Signal>,order:string[],defaultState:string,hold=0):string[]{const inputs=Object.values(signals),first=inputs[0];if(!first)return [];if(inputs.some(s=>s.revisionId!==first.revisionId||s.sampleRateHz!==first.sampleRateHz||s.values.length!==first.values.length))throw Error('Priority inputs must use the same media revision and sampling grid.');if(hold<0)throw Error('Priority hold cannot be negative.');const output:string[]=[],min=Math.ceil(hold*first.sampleRateHz);let current=defaultState,until=0;for(let i=0;i<first.values.length;i++){const chosen=order.find(id=>signals[id]?.values[i]>.5)??defaultState;if(chosen!==current&&i>=until){current=chosen;until=i+min;}output.push(current);}return output;}
